import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { gzipSync } from 'node:zlib';

// Attribute a route's first-load client JS to source modules/packages using client source maps.
// Requires a build made with `node scripts/performance/next-client-build.mjs <tree> build-sourcemaps`
// (chunk bytes equal a normal build apart from the sourceMappingURL comment).
//
//   node scripts/performance/route-first-load-modules.mjs <root> <route, e.g. /login> [--top 30] [--modules] [--route-only]
//
// Raw bytes are exact generated-code bytes per source; "~gzip" scales each chunk's gzip size by
// that share, so it is an estimate. Routes use Next's URL form from route-bundle-stats.json.
const args = process.argv.slice(2);
const flag = (name) => args.includes(name);
const option = (name) => {
  const index = args.indexOf(name);
  return index < 0 ? null : args[index + 1];
};
const [rootArgument = '.', route = '/'] = args.filter(
  (value, index) => !value.startsWith('--') && args[index - 1] !== '--top',
);
const root = resolve(rootArgument);
const top = Number(option('--top') ?? 30);
const stats = JSON.parse(readFileSync(resolve(root, '.next/diagnostics/route-bundle-stats.json'), 'utf8'));
const entry = stats.find((value) => value.route === route);
if (!entry) throw new Error(`Unknown route ${route}; see .next/diagnostics/route-bundle-stats.json`);
let chunks = entry.firstLoadChunkPaths;
if (flag('--route-only')) {
  const common = stats.map((value) => new Set(value.firstLoadChunkPaths)).reduce((a, b) => a.intersection(b));
  chunks = chunks.filter((chunk) => !common.has(chunk));
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const decodeTable = new Map([...BASE64].map((character, index) => [character, index]));
function decodeSegment(text) {
  const values = [];
  let value = 0;
  let shift = 0;
  for (const character of text) {
    const digit = decodeTable.get(character);
    value += (digit & 31) << shift;
    if (digit & 32) shift += 5;
    else {
      values.push(value & 1 ? -(value >>> 1) : value >>> 1);
      value = 0;
      shift = 0;
    }
  }
  return values;
}

// Adds generated byte counts per source for one (non-index) map whose code starts at line/column offset.
function attribute(map, lines, lineOffset, columnOffset, totals) {
  let sourceIndex = 0;
  const generatedLines = map.mappings.split(';');
  for (let line = 0; line < generatedLines.length; line += 1) {
    const text = lines[line + lineOffset];
    if (text == null) break;
    const startColumn = line === 0 ? columnOffset : 0;
    let column = 0;
    const segments = [];
    for (const raw of generatedLines[line].split(',')) {
      if (!raw) continue;
      const values = decodeSegment(raw);
      column += values[0];
      if (values.length > 1) sourceIndex += values[1];
      segments.push([startColumn + column, values.length > 1 ? sourceIndex : null]);
    }
    // Columns are UTF-16 offsets; measure UTF-8 bytes of each covered slice.
    for (let index = 0; index < segments.length; index += 1) {
      const [from, source] = segments[index];
      const to = index + 1 < segments.length ? segments[index + 1][0] : text.length;
      const slice = text.slice(from, to);
      const name = source == null ? '[unmapped]' : (map.sources[source] ?? '[unknown]');
      // Modules without source maps (JSON, some generated code) follow the previous module's last
      // mapping; split them off at the next Turbopack module factory boundary.
      const boundary = slice.slice(1).search(/[}\]],\d+,(?:\([a-z,]*\)|[a-z])=>/);
      const own = boundary < 0 ? slice : slice.slice(0, boundary + 2);
      const rest = boundary < 0 ? '' : slice.slice(boundary + 2);
      totals.set(name, (totals.get(name) ?? 0) + Buffer.byteLength(own));
      if (rest) {
        const kind = /^,\d+,[^{]*\{[a-z]\.exports=JSON\.parse\(/.test(rest) ? 'json module' : 'module';
        const label = `[unmapped ${kind} after ${name.replace(/^.*\/(?!$)/, '')}]`;
        totals.set(label, (totals.get(label) ?? 0) + Buffer.byteLength(rest));
      }
    }
  }
}

const perSource = new Map();
let missingMaps = 0;
for (const chunk of chunks) {
  const path = resolve(root, chunk);
  const code = readFileSync(path);
  // Turbopack names the map in the trailing sourceMappingURL comment (not always `<chunk>.map`).
  const url = code.toString('utf8').match(/\/\/# sourceMappingURL=([^\s]+)\s*$/)?.[1];
  const mapPath = url ? resolve(dirname(path), url) : `${path}.map`;
  if (!existsSync(mapPath)) {
    missingMaps += 1;
    continue;
  }
  const map = JSON.parse(readFileSync(mapPath, 'utf8'));
  const lines = code.toString('utf8').split('\n');
  const totals = new Map();
  if (map.sections) {
    for (const section of map.sections)
      attribute(section.map, lines, section.offset.line, section.offset.column, totals);
  } else attribute(map, lines, 0, 0, totals);
  const ratio = gzipSync(code, { level: 9 }).length / code.length;
  for (const [source, bytes] of totals) {
    const value = perSource.get(source) ?? { raw: 0, gzip: 0 };
    value.raw += bytes;
    value.gzip += bytes * ratio;
    perSource.set(source, value);
  }
}
if (missingMaps === chunks.length)
  throw new Error('No client source maps; build with next-client-build.mjs build-sourcemaps');

const normalize = (source) =>
  source
    .replace(/^turbopack:\/\/\/(?:\[project\]\/)?/, '')
    .replace(/^(?:.*\/)?node_modules\/\.pnpm\/[^/]+\/node_modules\//, 'node_modules/');
const packageOf = (source) => {
  const match = source.match(/^node_modules\/((?:@[^/]+\/)?[^/]+)/);
  return match ? match[1] : source.split('/').slice(0, 2).join('/');
};
const groups = new Map();
for (const [source, value] of perSource) {
  const key = flag('--modules') ? normalize(source) : packageOf(normalize(source));
  const group = groups.get(key) ?? { raw: 0, gzip: 0 };
  group.raw += value.raw;
  group.gzip += value.gzip;
  groups.set(key, group);
}
const kb = (bytes) => `${(bytes / 1024).toFixed(1)} kB`.padStart(10);
const total = [...groups.values()].reduce((sum, value) => sum + value.raw, 0);
console.log(
  `${route}: ${chunks.length} first-load chunks${flag('--route-only') ? ' (route-only)' : ''}, ${kb(total)} raw; ${missingMaps} without maps`,
);
console.log(`${'raw'.padStart(10)} ${'~gzip'.padStart(10)}  ${flag('--modules') ? 'module' : 'package / directory'}`);
for (const [key, value] of [...groups].sort((a, b) => b[1].raw - a[1].raw).slice(0, top)) {
  console.log(`${kb(value.raw)} ${kb(value.gzip)}  ${key}`);
}
